-- Richer product details for the storefront product page.
-- Applied once. Do not edit this file after it has been recorded in schema_migrations.

ALTER TABLE products
  ADD COLUMN model_name VARCHAR(160) NULL AFTER height,
  ADD COLUMN material VARCHAR(160) NULL AFTER model_name,
  ADD COLUMN size_label VARCHAR(160) NULL AFTER material,
  ADD COLUMN warranty VARCHAR(255) NULL AFTER size_label,
  ADD COLUMN key_features TEXT NULL AFTER warranty,
  ADD COLUMN box_contents TEXT NULL AFTER key_features;
